async function loadTerrain(live){const key=state.id+':'+(live?.Picture?.File||'');if(key===terrainKey)return;terrainKey=key;terrain=null;if(!live?.Picture)return;try{const r=await fetch('/api/live/picture?id='+state.id,{headers:{Authorization:'Bearer '+token}});if(!r.ok)return;const url=URL.createObjectURL(await r.blob()),img=new Image();img.onload=()=>{URL.revokeObjectURL(url);if(terrainKey===key){terrain=img;drawMap()}};img.onerror=()=>URL.revokeObjectURL(url);img.src=url}catch{}}

function drawMap(){const c=$('#battlefield');if(!c)return;const rect=c.getBoundingClientRect(),dpr=devicePixelRatio||1;c.width=Math.round(rect.width*dpr);c.height=Math.round(rect.height*dpr);const g=c.getContext('2d');g.scale(dpr,dpr);const w=rect.width,h=rect.height;g.clearRect(0,0,w,h);g.strokeStyle='#38586a33';g.lineWidth=1;for(let x=0;x<w;x+=40){g.beginPath();g.moveTo(x,0);g.lineTo(x,h);g.stroke()}for(let y=0;y<h;y+=40){g.beginPath();g.moveTo(0,y);g.lineTo(w,y);g.stroke()}const l=state.live?.Live;mapPoints=[];if(!l){g.fillStyle='#779ab2';g.font='12px Segoe UI';g.textAlign='center';g.fillText('Waiting for live battlefield data',w/2,h/2);return}const points=[...list(l.Flags),...list(l.Players)];if(!points.length)return;let xs=points.map(p=>p.X),zs=points.map(p=>p.Z);let minX=Math.min(...xs),maxX=Math.max(...xs),minZ=Math.min(...zs),maxZ=Math.max(...zs);if(l.Picture){minX=Math.min(minX,l.Picture.MinX);maxX=Math.max(maxX,l.Picture.MaxX);minZ=Math.min(minZ,l.Picture.MinZ);maxZ=Math.max(maxZ,l.Picture.MaxZ)}const scale=Math.min((w-80)/Math.max(50,maxX-minX),(h-80)/Math.max(50,maxZ-minZ))*state.zoom;const px=x=>w/2+(x-(minX+maxX)/2)*scale*(state.flipX?-1:1)+state.panX,py=z=>h/2-(z-(minZ+maxZ)/2)*scale*(state.flipZ?-1:1)+state.panY;if(terrain&&l.Picture){const p=l.Picture;g.save();g.globalAlpha=.65;g.translate(px(p.MinX),py(p.MaxZ));g.scale(state.flipX?-1:1,state.flipZ?-1:1);g.drawImage(terrain,0,0,Math.abs(p.MaxX-p.MinX)*scale,Math.abs(p.MaxZ-p.MinZ)*scale);g.restore()}const heat=list(state.live.Heat),top=Math.max(1,...heat.map(p=>p[2]));for(const p of heat){g.fillStyle=`rgba(255,123,50,${.08+.55*p[2]/top})`;g.fillRect(px(p[0])-5*scale,py(p[1])-5*scale,Math.max(3,10*scale),Math.max(3,10*scale))}for(const f of list(l.Flags)){const x=px(f.X),y=py(f.Z);g.strokeStyle=f.Owner===1?'#86ceff':f.Owner===2?'#ff995e':'#d5e2ed';g.lineWidth=1.5;g.beginPath();g.moveTo(x,y-9);g.lineTo(x+9,y);g.lineTo(x,y+9);g.lineTo(x-9,y);g.closePath();g.stroke();g.fillStyle='#e1eff8';g.textAlign='center';g.font='10px Segoe UI';g.fillText(f.Name,x,y-15)}for(const p of list(l.Players)){const x=px(p.X),y=py(p.Z),selected=p.Name===state.selected;mapPoints.push({x,y,name:p.Name});g.globalAlpha=p.Alive?1:.3;const color=p.Team===1?'#83d0ff':'#ff985c';g.strokeStyle=color;g.fillStyle=color;if(state.showRoutes&&(selected||!state.selected)){g.globalAlpha=.22;g.beginPath();g.moveTo(x,y);for(const pt of list(p.Route)){if(Array.isArray(pt))g.lineTo(px(pt[0]),py(pt[1]))}if(p.HasGoal)g.lineTo(px(p.GoalX),py(p.GoalZ));g.stroke();g.globalAlpha=p.Alive?1:.3}g.beginPath();g.arc(x,y,p.Bot?3:5,0,Math.PI*2);g.fill();if(p.Vehicle){g.strokeRect(x-5,y-5,10,10)}if(selected){g.lineWidth=1.5;g.beginPath();g.arc(x,y,10,0,Math.PI*2);g.stroke();g.fillStyle='#fff';g.textAlign='left';g.font='11px Segoe UI';g.fillText(p.Name,x+13,y-10)}g.globalAlpha=1}g.fillStyle='#7098b4';g.font='10px Consolas';g.textAlign='left';g.fillText(`${l.Players.length} entities / ${Math.round(100/state.zoom)}% map span`,14,h-15)}
function bindCanvas(){const c=$('#battlefield'),pointers=new Map();let moved=0,start=null,pinch=null;c.onwheel=e=>{e.preventDefault();state.zoom=Math.min(12,Math.max(.3,state.zoom*(e.deltaY<0?1.12:.89)));drawMap()};c.onpointerdown=e=>{c.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.offsetX,y:e.offsetY});moved=0;start={x:e.offsetX,y:e.offsetY,px:state.panX,py:state.panY};pinch=null};c.onpointermove=e=>{if(!pointers.has(e.pointerId))return;const prev=pointers.get(e.pointerId);pointers.set(e.pointerId,{x:e.offsetX,y:e.offsetY});if(pointers.size===2){const a=[...pointers.values()],d=Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y);if(pinch)state.zoom=Math.min(12,Math.max(.3,state.zoom*d/pinch));pinch=d;moved=20}else{state.panX+=e.offsetX-prev.x;state.panY+=e.offsetY-prev.y;moved+=Math.abs(e.offsetX-prev.x)+Math.abs(e.offsetY-prev.y)}drawMap()};c.onpointerup=e=>{pointers.delete(e.pointerId);if(moved<8){const closest=mapPoints.map(p=>({...p,d:Math.hypot(p.x-e.offsetX,p.y-e.offsetY)})).sort((a,b)=>a.d-b.d)[0];state.selected=closest&&closest.d<20?closest.name:null;drawMap();liveDetail()}pinch=null};c.onpointercancel=e=>{pointers.delete(e.pointerId);pinch=null};}
window.addEventListener('resize',()=>{if(state.page==='live')drawMap()});
async function renderLearning(epoch){
 let d;try{d=await api('/api/learning')}catch(e){if(epoch!==state.epoch)return;$('#main').innerHTML=heading('INTELLIGENCE / LEARNING LIBRARY','Learning library')+`<div class="notice warn">${esc(e.message)}</div><button id="learning-retry">Refresh library</button>`;$('#learning-retry').onclick=renderPage;return}if(epoch!==state.epoch)return;
 $('#main').innerHTML=heading('INTELLIGENCE / LEARNING LIBRARY','Experience that stays.','Inspect and manage the routes, hazards and landing spots your bots remember.','<button id="learning-refresh" class="small">↻ Refresh library</button>')+`<div class="notice">Learning folder: <span class="mono">${esc(d.Directory||'BotMod_learned')}</span><br>${d.Exists===false?'This folder has not been created yet. Bots create learning data during play.':'Reading existing learned data. Imports merge with the existing files.'}</div>${list(d.Warnings).length?`<div class="notice warn" role="status">${list(d.Warnings).map(esc).join('<br>')}</div>`:''}<div class="actions" style="margin-bottom:20px"><button id="export-learn" data-command ${!d.Exists?'disabled':''}>↓ Export all learning</button><label style="margin:0">Import ZIP <input type="file" id="import-learn" accept=".zip" class="file-input"></label><button id="import-go" data-command>Merge import</button></div>${panel('Learned battlefields',table(['MAP / MODE','SPOTS','DEATH CELLS','ROUTES','PADS',''],list(d.Files).map(f=>`<tr><td>${esc(mapName(f.Level))}<div class="hint">${esc(modeName(f.Mode))}${f.Skipped?' · '+f.Skipped+' entries skipped in view':''}</div></td><td>${f.Spots}</td><td>${f.Heat}</td><td>${f.Routes}</td><td>${f.Pads}</td><td><button data-learn-key="${esc(f.Key)}">Inspect</button></td></tr>`).join(''),'No readable learned maps yet. Use Refresh after a round has saved learning.'))}<p class="hint">Material library: ${d.Breakable?.Breakable||0} breakable / ${d.Breakable?.Unbreakable||0} solid materials.</p><div id="learn-details"></div>`;
 $('#learning-refresh').onclick=renderPage;$('#export-learn').onclick=()=>act('/api/learning/export',{},out=>download64(out.Data,out.Name,'application/zip'));$('#import-go').onclick=async()=>{const f=$('#import-learn').files[0];if(!f){toast('Choose a learning ZIP first.');return}if(f.size>16*1024*1024){toast('Learning ZIP must be under 16 MB.',true);return}if(!await confirmAction('Merge these learned files?','New entries will be added to the existing learning library.'))return;const data=await file64(f);act('/api/learning/import',{data},()=>renderPage())};$$('[data-learn-key]').forEach(b=>b.onclick=()=>inspectLearn(b.dataset.learnKey));
}
async function inspectLearn(key,offset=0){const epoch=state.epoch;try{
 const data=await api('/api/learning/file?key='+encodeURIComponent(key)+'&offset='+offset);if(epoch!==state.epoch||!$('#learn-details'))return;state.learnData=data;const entries=list(data.Entries),total=data.Total??entries.length,start=data.Offset||0,limit=data.Limit||100;
 $('#learn-details').innerHTML=panel(esc(key),`<p>Select entries to remove. Unknown and malformed lines stay unchanged on disk.</p>${data.Skipped?`<div class="notice warn">${data.Skipped} incomplete entries were skipped in this view. ${list(data.Warnings).map(esc).join(' ')}</div>`:''}<div class="actions"><button id="learn-all" class="small">Select this page</button><button id="learn-delete" class="danger" data-command>Remove selected entries</button></div><div class="learning-pages"><button id="learn-prev" class="small" ${start===0?'disabled':''}>← Previous</button><span class="hint">${total?`${start+1}–${Math.min(total,start+entries.length)} of ${total}`:'No entries'}</span><button id="learn-next" class="small" ${start+entries.length>=total?'disabled':''}>Next →</button></div>`+table(['','TYPE','LOCATION','WHAT IT DOES'],entries.map((e,i)=>`<tr><td><input type="checkbox" data-entry="${i}" aria-label="Select entry ${start+i+1}"></td><td>${esc(e.Type)}<div class="hint">${esc(e.Kind)}</div></td><td class="mono">${Math.round(e.X)}, ${Math.round(e.Z)}</td><td class="learn-entry">${esc(e.Effect)}<div class="hint">${esc(e.Status)}</div></td></tr>`).join('')));
 $('#learn-prev').onclick=()=>inspectLearn(key,Math.max(0,start-limit));$('#learn-next').onclick=()=>inspectLearn(key,start+limit);$('#learn-all').onclick=()=>{const all=$$('[data-entry]'),checked=all.some(x=>!x.checked);all.forEach(x=>x.checked=checked)};$('#learn-delete').onclick=async()=>{const lines=$$('[data-entry]:checked').map(x=>entries[+x.dataset.entry].Line);if(!lines.length){toast('Select at least one entry.');return}if(await confirmAction(`Remove ${lines.length} learned entries?`,'This changes the learned file on disk. A first-edit backup is kept.'))act('/api/learning/delete',{key,lines,revision:data.Revision},async()=>{await renderPage();await inspectLearn(key,start)})};$('#learn-details').scrollIntoView({behavior:'smooth',block:'start'});
 }catch(e){toast(e.message,true)}}
function download64(data,name,type){const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0)),u=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
function file64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file)})}
async function renderServices(epoch){const services=list(state.status.Services),local=state.meta.Local;$('#main').innerHTML=heading('SYSTEMS / BF-PORTABLE','Bring it all online.','Launch the original service stack in its existing order, with live progress.')+(!state.meta.Elevated?'<div class="notice warn">This launcher is not elevated. Components that require administrator rights may ask on the host PC. Use Command-Admin.bat when your BF-Portable setup requires it.</div>':'')+`<div class="two-col"><div>${panel('One-click deployment',`<p>The existing launcher configuration controls program paths, service order, timing and launch windows.</p><div class="checks">${list(state.status.Servers).map(s=>`<label><input type="checkbox" data-launch-id="${s.Number}" ${list(state.meta.LaunchServers).length?(list(state.meta.LaunchServers).map(Number).includes(+s.Number)?'checked':''):'checked'}>${esc(s.Label)}</label>`).join('')}</div><div class="checks"><label><input type="checkbox" id="launch-dns" ${state.meta.StartDns?'checked':''}>Include LAN DNS</label></div><div class="actions"><button class="primary" id="launch-all" data-command>Launch BF-Portable ↗</button><button id="services-refresh">↻ Refresh status</button></div><div id="service-launch-log" class="log" style="margin-top:18px">${esc(list(state.status.Launch?.Log).join('\n')||'Ready to launch.')}</div>`)}${panel('Services',services.map(s=>`<div class="service-row"><div><h3>${esc(s.Label)}</h3><small>${esc(s.State.toUpperCase())}${s.Port?' · TCP '+s.Port:''}</small></div><div class="actions"><button class="small" data-service="${s.Key}" data-operation="start">Start</button><button class="small" data-service="${s.Key}" data-operation="stop">Stop</button></div></div>`).join(''))}</div><div>${panel('Client & original launcher',`<p>Open the game launcher on the host PC, or use the original desktop launcher (Server Control) for saved accounts, LAN backend discovery, registration, quick join and its embedded Battlelog.</p><div class="actions"><button id="open-client" ${local?'':'disabled'}>Open BF Launcher ↗</button><button id="open-original" ${local?'':'disabled'}>Original launcher ↗</button></div>${!local?'<p class="hint">These actions run on the host PC. Open Command there to use them.</p>':''}`)}${panel('Launcher configuration',`<p>Program paths, service flags, DNS, timing and startup options use your existing Launcher.json.</p><button id="edit-launcher" ${local?'':'disabled'}>Edit launcher configuration</button><div id="launcher-config"></div>`)}${panel('Local network',`<p>Pair a phone using the host’s current network address. Change server and bot settings while your match runs.</p><button id="services-pair">Show phone QR code</button><p class="hint">${esc(state.meta.Ips.join(' · ')||'No LAN adapter detected')}</p>`)}${panel('Backend IP targets',`<p>Use the original IP helpers to update only the targets you select. Existing .before-ip backups are preserved.</p><button id="edit-ip" ${local?'':'disabled'}>Review backend addresses</button><div id="ip-targets"></div>`)}</div></div>`;
 $('#launch-all').onclick=()=>act('/api/launch',{servers:$$('[data-launch-id]:checked').map(x=>+x.dataset.launchId),dns:$('#launch-dns').checked},()=>navigate('overview'));$('#services-refresh').onclick=()=>refreshStatus().then(renderPage).catch(e=>toast(e.message,true));$$('[data-service]').forEach(b=>b.onclick=async()=>{if(b.dataset.operation==='stop'&&!await confirmAction('Stop this service?','Stopping a backend service can interrupt connected players.'))return;act('/api/services',{key:b.dataset.service,action:b.dataset.operation},()=>renderPage())});$('#open-client').onclick=()=>act('/api/client',{});$('#open-original').onclick=()=>act('/api/desktop',{});$('#services-pair').onclick=showPair;$('#edit-launcher').onclick=()=>editLauncher();$('#edit-ip').onclick=()=>editIp();
}
async function editLauncher(){try{const d=await api('/api/launcher/config'),cfg=d.Config;$('#launcher-config').innerHTML=`<div class="notice">Changes apply to the next launch sequence. These are the same service options used by the original launcher.</div><div class="field"><label for="config-gap">Delay between servers (seconds)</label><input id="config-gap" type="number" min="0" max="120" value="${cfg.ServerGapSeconds}"></div><div class="field"><label for="config-window">Server window</label><select id="config-window">${['Normal','Minimized','Hidden'].map(x=>`<option ${cfg.ServerWindow===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="config-domain">LAN DNS domain</label><input id="config-domain" value="${esc(cfg.DnsDomain)}" placeholder="Your configured LAN domain"></div><div class="field"><label for="config-ip">LAN DNS address</label><input id="config-ip" value="${esc(cfg.DnsIp)}" placeholder="192.168.1.100"></div>${cfg.Parts.map((p,i)=>`<details class="service-config"><summary>${esc(p.Label)}</summary><div class="checks">${['Enabled','Admin','Required'].map(k=>`<label><input type="checkbox" data-part="${i}" data-config-key="${k}" ${p[k]?'checked':''}>${k==='Admin'?'Needs admin':k==='Required'?'Required to launch':'Enabled'}</label>`).join('')}</div>${[['Exe','Program path'],['Args','Arguments'],['WorkDir','Working directory'],['Proc','Process name'],['Port','TCP port · blank for process check'],['Wait','Startup timeout (seconds)'],['Input','Typed startup answers']].map(([k,label])=>`<div class="field"><label>${label}</label><input data-part="${i}" data-config-key="${k}" value="${esc(p[k])}"></div>`).join('')}<div class="field"><label>Window visibility</label><select data-part="${i}" data-config-key="Window">${['Normal','Minimized','Hidden'].map(x=>`<option ${p.Window===x?'selected':''}>${x}</option>`).join('')}</select></div></details>`).join('')}<button id="config-save" class="primary" style="margin-top:12px" data-command>Save launcher configuration</button>`;$$('#launcher-config input,#launcher-config select').forEach(x=>x.onchange=()=>dirty());$('#config-save').onclick=()=>{if(!$('#config-gap').reportValidity())return;cfg.ServerGapSeconds=+$('#config-gap').value;cfg.ServerWindow=$('#config-window').value;cfg.DnsDomain=$('#config-domain').value;cfg.DnsIp=$('#config-ip').value;$$('[data-config-key]').forEach(x=>{const k=x.dataset.configKey;let v=x.type==='checkbox'?x.checked:x.value;if(k==='Port')v=v===''?null:+v;if(k==='Wait')v=+v;cfg.Parts[+x.dataset.part][k]=v});act('/api/launcher/config/save',{config:cfg,revision:d.Revision},()=>{clearEdits();renderPage()})}}catch(e){toast(e.message,true)}}
