function showPair(){const d=$('#pair-dialog'),urls=state.meta.Urls;if(state.meta.LocalOnly){toast('Phone access is disabled in LocalOnly mode. Start Command.bat for LAN access.',true);return}if(!urls.length){toast('No LAN IPv4 address detected. Connect the PC to your local network and restart Command.',true);return}$('#lan-address').innerHTML=urls.map((u,i)=>`<option value="${i}">${esc(u.split('/#')[0])}</option>`).join('');const draw=()=>{const url=urls[+$('#lan-address').value];const qr=new CommandQR(-1,1);qr.addData(url);qr.make();const n=qr.getModuleCount();let path='';for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(qr.isDark(y,x))path+=`M${x+4} ${y+4}h1v1h-1z`;$('#qr').innerHTML=`<svg role="img" aria-label="Scan to pair your phone" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${n+8} ${n+8}"><rect width="100%" height="100%" fill="#fff"/><path d="${path}" fill="#000"/></svg>`;$('#pair-url').textContent=url.split('/#')[0];$('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast('Pairing link copied.')}catch{const input=document.createElement('textarea');input.value=url;d.append(input);input.select();const ok=document.execCommand('copy');input.remove();toast(ok?'Pairing link copied.':'Copy failed. Scan the QR code instead.',!ok)}}};$('#lan-address').onchange=draw;draw();d.showModal()}
